import json
import urllib.request
from typing import Callable

from .config import PAYMENTS_API_URL
from .errors import PaymentsUnavailable


def _default_opener(url: str, timeout: float) -> bytes:
    with urllib.request.urlopen(url, timeout=timeout) as response:
        return response.read()


class PaymentsClient:
    def __init__(self, base_url: str = PAYMENTS_API_URL, opener: Callable[[str, float], bytes] | None = None):
        self.base_url = base_url
        self.opener = opener or _default_opener

    def get_status(self, timeout: float = 2.0) -> dict:
        url = f"{self.base_url}/status"
        raw = self.opener(url, timeout)
        return json.loads(raw)

class PaymentsUnavailable(Exception):
    """Raised when the payments gateway can't be reached or returns garbage."""

    def __init__(self, cause: Exception | None = None):
        self.cause = cause
        message = "payments gateway unavailable"
        if cause is not None:
            message = f"{message}: {cause}"
        super().__init__(message)

from dataclasses import dataclass
from datetime import date

ALLOWED_CURRENCIES = {"USD", "EUR", "GBP", "JPY"}


@dataclass
class Invoice:
    customer_id: str
    amount_cents: int
    currency: str
    issue_date: date
    due_date: date


def validate_invoice(invoice: Invoice) -> list[str]:
    """Return a list of human-readable validation errors (empty = valid)."""
    errors: list[str] = []

    if invoice.amount_cents <= 0:
        errors.append("amount_cents must be positive")

    if invoice.currency not in ALLOWED_CURRENCIES:
        errors.append(f"unsupported currency: {invoice.currency}")

    if invoice.due_date > invoice.issue_date:
        errors.append("due_date must be on or after issue_date")

    return errors

from datetime import date

from paylink.invoice import Invoice, validate_invoice


def _invoice(**overrides):
    base = dict(
        customer_id="cust-1",
        amount_cents=1000,
        currency="USD",
        issue_date=date(2026, 1, 1),
        due_date=date(2026, 1, 15),
    )
    base.update(overrides)
    return Invoice(**base)


def test_valid_invoice_has_no_errors():
    assert validate_invoice(_invoice()) == []


def test_currency_check_is_case_insensitive():
    assert validate_invoice(_invoice(currency="usd")) == []


def test_non_positive_amount_is_rejected():
    errors = validate_invoice(_invoice(amount_cents=0))
    assert errors == ["amount_cents must be positive"]


def test_due_date_before_issue_date_is_rejected():
    errors = validate_invoice(
        _invoice(issue_date=date(2026, 3, 1), due_date=date(2026, 2, 1))
    )
    assert errors == ["due_date must be on or after issue_date"]

